// Isolated actual native FD4, biased advection, KO and full native22 linear
// source action. No interfaces, SAT, evolved gradients or time trajectory.
#include "goal1_native_endpoint.hpp"
#include "goal1_tensor_runtime.hpp"
#include "goal1_operator_oracle.hpp"
#include "utils/finite_diff.hpp"
#include <iostream>
#include <fstream>
#include <iomanip>
#include <vector>
namespace cs=cubed_sphere;namespace h=z4c::hyperboloidal;
struct Field{const std::vector<Real>*data;int field;Real operator()(int,int k,int j,int i)const{return (*data)[((k*7+j)*7+i)*22+field];}};
struct Velocity{Real v;Real operator()(int,int,int,int,int)const{return v;}};
std::array<Real,22>Values(const h::Z4cJet<Real>&u){std::array<Real,22>v{};for(int k=0;k<22;++k)v[k]=cs::operator_oracle::Component(u,k).value;return v;}
std::array<Real,22> Action(const h::Z4cJet<Real>&delta,const h::LayerPoint<Real>&ref,const Real x[3]){std::vector<Real>flat;cs::typed_support::Map<Real>(delta,[&](int,Real v){flat.push_back(v);return v;});auto state=cs::typed_support::Map<cs::Jet>(ref.state,[&](int k,Real v){cs::Jet q(v);q.d[0]=flat[k];return q;});auto f=cs::typed_support::Core(state,cs::typed_support::Constant<cs::Jet>(ref),cs::typed_support::Constant<cs::Jet>(rwm::ReferenceConnection(ref,x)));std::array<Real,22>out{};for(int k=0;k<22;++k)out[k]=f[k].d[0];return out;}
int main(int argc,char**argv){Kokkos::initialize(argc,argv);int status=0;try{if(argc!=2)throw std::runtime_error("uniform points argument");std::ifstream input(argv[1]);int id;Real x[3];cs::clock_oracle::Height height(48);h::LayerReference<Real>descriptor(1.,.5,{true,.05,.95});const int pairs_i[6]={0,0,0,1,1,2},pairs_j[6]={0,1,2,1,2,2};std::cout<<std::setprecision(17);
while(input>>id>>x[0]>>x[1]>>x[2]){Real radius=std::sqrt(x[0]*x[0]+x[1]*x[1]+x[2]*x[2]),n[3];for(int d=0;d<3;++d)n[d]=x[d]/radius;auto ref=descriptor.At(x[0],x[1],x[2]);auto coefficients=cs::tensor_oracle::Evaluate(radius,0,height);auto exact=cs::tensor_oracle::NativeJet(coefficients,radius,n,0);cs::tensor_oracle::Coeff ct;for(int k=0;k<15;++k)ct.c[k]=cs::tensor_oracle::Dt(coefficients.c[k]);auto target=Values(cs::tensor_oracle::NativeJet(ct,radius,n,0)),exactSource=Action(exact,ref,x);Real exactError=0;for(int k=0;k<22;++k)exactError=std::max(exactError,std::abs(exactSource[k]-target[k])/std::max({Real(1),std::abs(target[k]),std::abs(exactSource[k])}));
for(Real step:{Real(.025),Real(1./60),Real(.0125),Real(.00625),Real(.003125),Real(.0015625)}){std::vector<Real>data(7*7*7*22);Real idx[3]={1/step,1/step,1/step};
 for(int k=0;k<7;++k)for(int j=0;j<7;++j)for(int i=0;i<7;++i){Real p[3]={x[0]+(i-3)*step,x[1]+(j-3)*step,x[2]+(k-3)*step},r=std::sqrt(p[0]*p[0]+p[1]*p[1]+p[2]*p[2]),direction[3]{};if(r)for(int d=0;d<3;++d)direction[d]=p[d]/r;auto co=cs::tensor_oracle::Evaluate(r,0,height);auto v=Values(cs::tensor_oracle::NativeJet(co,r,direction,0));for(int field=0;field<22;++field)data[((k*7+j)*7+i)*22+field]=v[field];}
 std::array<std::array<Real,13>,22>jet{};Real first=0,second=0;const Real unit=.20282536946068094,L=.15;
 for(int field=0;field<22;++field){Field f{&data,field};auto q=cs::operator_oracle::Component(exact,field);bool config=field<7||field>=18;Real scale=config?unit:unit/L;jet[field][0]=f(0,3,3,3);for(int d=0;d<3;++d){jet[field][1+d]=::Dx<3>(d,idx,f,0,3,3,3);first+=std::pow((jet[field][1+d]-q.d[d])*L/scale,2);for(int e=0;e<3;++e){jet[field][4+3*d+e]=d==e?::Dxx<3>(d,idx,f,0,3,3,3) : ::Dxy<3>(d,e,idx,f,0,3,3,3);if(config)second+=std::pow((jet[field][4+3*d+e]-q.dd[d][e])*L*L/scale,2);}}}
 std::vector<Real>flat;auto scalar=[&](int field){flat.push_back(jet[field][0]);for(int d=0;d<3;++d)flat.push_back(jet[field][1+d]);for(int a=0;a<6;++a)flat.push_back(jet[field][4+3*pairs_i[a]+pairs_j[a]]);};for(int f:{0,18,7,17})scalar(f);for(int i=0;i<3;++i){scalar(19+i);scalar(14+i);}for(int i=0;i<6;++i){scalar(1+i);flat.push_back(jet[8+i][0]);for(int d=0;d<3;++d)flat.push_back(jet[8+i][1+d]);}h::Z4cJet<Real>zero{};auto delta=cs::typed_support::Map<Real>(zero,[&](int k,Real){return flat.at(k);});auto source=Action(delta,ref,x);Real core=0,upwind=0,full=0;
 for(int field=0;field<22;++field){Field f{&data,field};bool config=field<7||field>=18;Real scale=config?unit:unit/L,adv=0,ko=0;for(int d=0;d<3;++d){adv+=::Lx<3>(d,idx,Velocity{ref.beta[d]},f,0,d,3,3,3)-ref.beta[d]*jet[field][1+d];const Real c[4]={-1,3,-3,1};for(int l=0;l<4;++l){Real third=0;for(int b=0;b<4;++b){int p[3]={3,3,3};p[d]+=b-l;third+=c[b]*f(0,p[2],p[1],p[0]);}ko-=.1*c[l]*third/(64*step);}}core+=std::pow((source[field]-target[field])*L/scale,2);upwind+=std::pow((source[field]+adv-target[field])*L/scale,2);full+=std::pow((source[field]+adv+ko-target[field])*L/scale,2);}
 std::cout<<"{\"point\":"<<id<<",\"h\":"<<step<<",\"first_Lscaled_error\":"<<std::sqrt(first)<<",\"configuration_Hessian_Lscaled_error\":"<<std::sqrt(second)<<",\"native_core_Lscaled_error\":"<<std::sqrt(core)<<",\"native_core_upwind_Lscaled_error\":"<<std::sqrt(upwind)<<",\"native_core_upwind_KO_Lscaled_error\":"<<std::sqrt(full)<<",\"exact_jet_actual_source_scaled_error\":"<<exactError<<"}"<<std::endl;
}}}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;status=2;}Kokkos::finalize();return status;}
